## Import

```tsx
import CodeSnippet from "../src/components/codesnippet";
```

---

## Example

```tsx
import CodeSnippet from "../src/components/codesnippet";

export default function CodeSnippetExample() {
  return (
    <CodeSnippet
      language="tsx"
      code={`import { Button } from "@toni-toni-choppa/ui-kit";`}
    />
  );
}
```

---

## Props

- `language: string` (required): label shown in the snippet header.
- `code: string` (required): snippet content to render and copy.

---

## Notes

- This component is currently used by the docs renderer for fenced code blocks.
- Clicking `Copy` writes the code content to the clipboard.

## Import

```tsx
import { Input } from "@toni-toni-choppa/ui-kit";
```

---

## Example

```tsx
import { useState } from "react";
import { Input } from "@toni-toni-choppa/ui-kit";

export default function CheckboxExample() {
  const [termsAccepted, setTermsAccepted] = useState(false);

  return (
    <Input.Checkbox
      id="terms"
      label="I accept the terms"
      onChange={setTermsAccepted}
    />
  );
}
```

---

## Props

- `id: string` (required): `id` for the checkbox input.
- `label: string` (required): visible label text.
- `onChange: (checked: boolean) => void` (required): callback with checked state.
- `disabled?: boolean`: disables interaction.

## Import

```tsx
import { Input } from "@toni-toni-choppa/ui-kit";
```

